-- Oficial Investigador
update public.syllabus_topics set discipline = 'Língua Portuguesa', topic_text = 'LÍNGUA PORTUGUESA (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Interpretação e Compreensão de texto. 2. Organização estrutural dos textos. 3. Marcas de textualidade: coesão, coerência e intertextualidade. 4. Modos de organização discursiva: descrição, narração, exposição, argumentação e injunção; características específicas de cada modo. 5. Tipos textuais: informativo, publicitário, propagandístico, normativo, didático e divinatório; características específicas de cada tipo. 6. Textos literários e não literários. 7. Tipologia da frase portuguesa. 8. Estrutura da frase portuguesa: operações de deslocamento, substituição, modificação e correção. 9. Problemas estruturais das frases. 10. Norma culta. 11. Pontuação e sinais gráficos. 12. Organização sintática das frases: termos e orações. 13. Ordem direta e inversa. 14. Tipos de discurso. 15. Registros de linguagem. 16. Funções da linguagem. 17. Elementos dos atos de comunicação. 18. Estrutura e formação de palavras. 19. Formas de abreviação. 20. Classes de palavras; os aspectos morfológicos, sintáticos, semânticos e textuais de substantivos, adjetivos, artigos, numerais, pronomes, verbos, advérbios, conjunções e interjeições; os modalizadores. 21. Semântica: sentido próprio e figurado; antônimos, sinônimos, parônimos e hiperônimos. 22. Polissemia e ambiguidade. 23. Os dicionários: tipos; a organização de verbetes. 24. Vocabulário: neologismos, arcaísmos, estrangeirismos; latinismos. 25. Ortografia e acentuação gráfica. 26. A crase.', content_status = 'current' where id = 'b9661d05-849c-4b38-8ae5-3c28ee50a948' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Raciocínio Lógico Matemático, Estatístico e Contábil', topic_text = 'RACIOCÍNIO LÓGICO MATEMÁTICO, ESTATÍSTICO E CONTÁBIL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Lógica: proposições, conectivos, equivalências lógicas, quantificadores e predicados. 2. Conjuntos e suas operações, diagramas. 3. Números inteiros, racionais e reais e suas operações, porcentagem e juros. 4. Proporcionalidade direta e inversa. 5. Medidas de comprimento, área, volume, massa e tempo. 6. Estrutura lógica de relações arbitrárias entre pessoas, lugares, objetos ou eventos fictícios; dedução de novas informações das relações fornecidas e avaliação das condições usadas para estabelecer a estrutura daquelas relações. 7. Compreensão e análise da lógica de uma situação, utilizando as funções intelectuais: raciocínio verbal, raciocínio matemático, raciocínio sequencial, orientação espacial e temporal, formação de conceitos, discriminação de elementos. 8. Compreensão de dados apresentados em gráficos e tabelas. 9. Noções de estatística: conceitos básicos, medidas de tendência central e de dispersão, interpretação de distribuições. 10. Raciocínio lógico envolvendo problemas aritméticos, geométricos e matriciais. 11. Problemas de contagem e noções de probabilidade. 12. Geometria básica: ângulos, triângulos, polígonos, distâncias, proporcionalidade, perímetro e área. 13. Plano cartesiano: sistema de coordenadas, distância. 14. Problemas de lógica e raciocínio. 15. Noções de contabilidade: estrutura conceitual; elementos patrimoniais e de resultado (ativo, passivo, patrimônio líquido, receita e despesa); regimes de caixa e de competência; balanço patrimonial; demonstração do resultado.', content_status = 'current' where id = '2a233f18-e893-492c-9f74-2fb1a8da9100' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Informática', topic_text = 'INFORMÁTICA (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Conceitos fundamentais de hardware, software, periféricos e componentes de um sistema computacional; 2 Sistemas operacionais Windows e Linux: estrutura de diretórios e arquivos, permissões de acesso, ocultação e localização de arquivos, uso básico de linha de comando (CMD, PowerShell e Bash; 3. Ferramentas de produtividade do Microsoft Office e Libre Office(editor de texto, editor planilhas eletrônicas e editor de apresentações); 4. Redes de computadores e internet: endereçamento IP,DNS, gateway padrão, conceitos de roteamento, NAT e proxy, protocolos HTTP, HTTPS, FTP, SMTP e IMAP, uso de VPNs; 5. Segurança da informação: malware: vírus, worms, cavalos de Troia (trojans), spyware, ransomware, backdoor, zero-day exploits e keyloggers, phishing, baiting e engenharia social: métodos e canais utilizados; 6. Navegadores, correio eletrônico e redes sociais: funcionamento de navegadores, uso de cache, cookies e histórico, análise de cabeçalhos de e-mails; 7. Conceitos de hash, criptografia, assinatura digital e certificação digital, autenticação de dois fatores. Noções de backup e análise de dispositivos: conceito de imagem forense, hash de integridade, partições, sistemas de arquivos e mídias removíveis; 8. Noções de bancos de dados e dados; 9. Legislação digital aplicada à investigação: princípios e aplicações do Marco Civil da Internet, Lei Carolina Dieckmann, Lei Geral de Proteção de Dados (LGPD), Lei dos Crimes Cibernéticos e Lei de Interceptações Telefônicas e Telemáticas. 10 Noções de aprendizado de máquina, IA Generativa: principais características.', content_status = 'current' where id = 'd7de8327-3793-45a7-94ca-bb87b7a0a86a' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Conhecimentos sobre o Estado do Piauí', topic_text = 'CONHECIMENTOS SOBRE O ESTADO DO PIAUÍ (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Aspectos históricos relevantes do Estado do Piauí: formação territorial, processos coloniais e movimentos sociais locais; 2. Geografia física e humana: relevo, clima, hidrografia, vegetação, população, densidade demográfica e principais atividades econômicas; 3. Divisão político-administrativa: estrutura do estado, municípios e regiões de desenvolvimento; 4. Cultura piauiense: manifestações culturais, patrimônio material e imaterial, festas populares, artes, literatura, música e tradições; 5. Indicadores sociais e econômicos recentes: IDH, segurança pública, saúde, educação, mobilidade e desenvolvimento regional; 6. Estrutura do governo estadual, políticas públicas, programas sociais e desafios contemporâneos; 7. Temas de atualidade que impactam o Estado do Piauí: segurança, economia, meio ambiente, políticas de inclusão e sustentabilidade. Conhecimentos Específicos:', content_status = 'current' where id = '62c80a39-2b57-4bfe-901b-dea480d4a543' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Direito Penal', topic_text = 'DIREITO PENAL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Princípios básicos do Direito Penal; 2. Aplicação da lei penal: lei penal no tempo e no espaço; tempo e lugar do crime; territorialidade e extraterritorialidade; 3. Crimes: classificação; fato típico e elementos; crime consumado e tentado; desistência voluntária e arrependimento eficaz; crime impossível; dolo e culpa; erro; ilicitude e causas de exclusão; excesso punível; culpabilidade; 4. Concurso de pessoas e concurso de crimes; 5. Penas: espécies e aplicação; 6. Extinção da punibilidade; 7. Crimes em espécie: contra a pessoa; contra o patrimônio; contra a propriedade imaterial; contra a dignidade sexual; contra a incolumidade pública; contra a paz pública; contra a fé pública; contra a administração pública; crimes cibernéticos; crimes de perseguição (stalking – Lei nº 14.132/2021); 8. Crimes previstos no Estatuto da Criança e do Adolescente (Lei nº 8.069/1990); 9. Crimes previstos no Estatuto do Idoso (Lei nº 10.741/2003); 10. Crimes de Organização Criminosa (Lei nº 12.850/2013); 11. Interceptação Telefônica (Lei nº 9.296/1996); 12. Crimes previstos no Código Eleitoral (Lei nº 4.737/1965); 13. Crimes de Trânsito (Lei nº 9.503/1997 – Código de Trânsito Brasileiro); 14. Juizados Especiais Criminais (Lei nº 9.099/1995, Capítulo III); 15. Crimes contra a Ordem Tributária, a Economia e as Relações de Consumo (Lei nº 8.137/1990); 16. Violência Doméstica e Familiar contra a Mulher (Lei nº 11.340/2006 – Lei Maria da Penha); 17. Crimes contra as Relações de Consumo (Título II da Lei nº 8.078/1990 – Código de Defesa do Consumidor); 18. Lei das Contravenções Penais (Decreto-Lei nº 3.688/1941); 19. Crimes contra o Meio Ambiente (Lei nº 9.605/1998); 20. Lavagem ou ocultação de bens, direitos e valores (Lei nº 9.613/1998); 21. Crimes previstos no Estatuto da Pessoa com Deficiência (Lei nº 13.146/2015); 22. Lei dos Crimes Hediondos (Lei nº 8.072/1990); 23. Estatuto do Desarmamento (Lei nº 10.826/2003); 24. Lei de Abuso de Autoridade (Lei nº 13.869/2019).', content_status = 'current' where id = '4b058969-78c3-455a-bcb2-0e6b9bdb9054' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Direito Processual Penal', topic_text = 'DIREITO PROCESSUAL PENAL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Inquérito policial: histórico, natureza, conceito, finalidade, características, fundamento, titularidade, grau de cognição, valor probatório, formas de instauração, notitia criminis, delatio criminis, procedimentos investigativos, indiciamento, garantias do investigado e conclusão; 2. Prova: preservação de local de crime, requisitos e ônus da prova, nulidade da prova, documentos de prova, reconhecimento de pessoas e coisas, acareação, indícios, busca e apreensão, cadeia de custódia; 3. Citações e intimações; 4. Nulidades; 5. Restrição de liberdade: prisão em flagrante, prisão preventiva, prisão temporária (Lei nº 7.960/1989 e Lei nº 8.072/1990), duração do mandado de prisão (Lei nº 13.869/2019), liberdade provisória e medidas cautelares diversas da prisão; 6. Banco de dados para registro dos mandados de prisão – CNJ (Lei nº 12.403/2011) e Banco Nacional de Medidas Penais e Prisões – BNMP 3.0 (Resolução CNJ nº 417/2021); 7. Audiência de custódia; 8. Emprego de algemas (Lei nº 13.434/2007 e Lei nº 7.210/1984); 9. Lei nº 1.079/1950 e Decreto-Lei nº 201/1967 (crimes de responsabilidade); 10. Procedimentos dos Juizados Especiais Criminais e Termo Circunstanciado (Lei nº 9.099/1995 e Lei nº 10.259/2001); 11. Investigação criminal digital: busca e apreensão de dispositivos eletrônicos, quebra de sigilo telemático, cadeia de custódia digital e noções de redes, protocolos de internet e crimes cibernéticos; 12. Leis processuais penais especiais: Lei nº 7.210/1984 (Execução Penal), Lei nº 9.296/1996 (Interceptação Telefônica), Lei nº 12.965/2014 (Marco Civil da Internet), Lei nº 14.155/2021 (alterações CPP/CP para crimes informáticos), Lei nº 9.613/1998 (lavagem de dinheiro – aspectos processuais), Lei nº 11.340/2006 (Lei Maria da Penha – aspectos processuais), Lei nº 13.964/2019 (Pacote Anticrime).', content_status = 'current' where id = 'c5f9e371-a50c-47c9-9087-b51a213d0720' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Direito Constitucional', topic_text = 'DIREITO CONSTITUCIONAL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Princípios fundamentais da Constituição da República de 1988; 2. Direitos e garantias fundamentais: direitos individuais e coletivos, sociais, de nacionalidade, políticos e dos trabalhadores; 3. Organização do Estado: União, Estados, Municípios e Distrito Federal; 4. Poderes da União: competências e limites dos Poderes Executivo, Legislativo e Judiciário; 5. Segurança pública no texto constitucional (art. 144): organização das polícias civis e militares; 6. Remédios constitucionais: habeas corpus, habeas data, mandado de segurança, mandado de injunção e ação popular; 7. Controle de constitucionalidade das leis: ação direta de inconstitucionalidade e ação declaratória; 8. Constituição do Estado do Piauí.', content_status = 'current' where id = 'f16d8862-b0b8-4a40-b7fd-c54f1591fff0' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Direito Administrativo', topic_text = 'DIREITO ADMINISTRATIVO (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Conceito, fontes e objeto do Direito Administrativo; 2. Princípios da administração pública: legalidade, impessoalidade, moralidade, publicidade, eficiência e princípios implícitos; 3. Disposições da Lei de Introdução às Normas do Direito Brasileiro (LINDB – Lei nº 13.655/2018) aplicáveis ao Direito Administrativo; 4. Administração pública direta e indireta: autarquias, fundações, empresas públicas e sociedades de economia mista; 5. Atos administrativos: requisitos, atributos, classificação, espécies, revogação, invalidação e convalidação; 6. Poderes administrativos: hierárquico, disciplinar, regulamentar e de polícia; abuso de poder e Lei de Abuso de Autoridade (Lei nº 13.869/2019); 7. Serviços públicos: conceito, características e formas de prestação; 8. Licitações e contratos administrativos: Lei nº 14.133/2021 e disposições aplicáveis; 9. Responsabilidade civil do Estado: teoria do risco administrativo, causas excludentes, responsabilidade por atos legislativos, judiciais e de agentes públicos; 10. Agentes públicos: cargos, empregos e funções; investidura, direitos, deveres e responsabilização; 11. Improbidade administrativa: Lei nº 8.429/1992, alterações posteriores, atos ímprobos, penalidades e procedimentos; 12. Lei Maria da Penha (Lei nº 11.340/2006): medidas protetivas, procedimentos e atuação policial;', content_status = 'current' where id = '6b961de6-1ad4-4da7-9261-012ebaa6c9f6' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Legislação Institucional da Polícia Civil', topic_text = 'LEGISLAÇÃO INSTITUCIONAL DA POLÍCIA CIVIL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Lei Complementar Estadual nº 37/2004 (Estatuto da Polícia Civil do Estado do Piauí): 1.1. Da organização da Polícia Civil: estrutura, competências e atribuições. 1.2. Das carreiras policiais civis: ingresso, desenvolvimento e progressão. 1.3. Dos direitos, deveres e prerrogativas dos servidores policiais civis. 1.4. Do regime disciplinar: transgressões, penalidades e procedimentos administrativos. 1.5. Do regime de trabalho, licenças e afastamentos. 1.6. Da aposentadoria e pensões especiais. 2. Lei Complementar Estadual nº 318/2025 (alterações da LC nº 37/2004): 2.1. Modificações na estrutura organizacional. 2.2. Alterações no regime de carreiras. 2.3. Mudanças nos direitos e deveres dos servidores. 2.4. Atualizações no regime disciplinar e procedimentos Decreto Nº 22.223/23 e suas alterações. 3. Lei Orgânica Nacional das Polícias Civis (Lei nº 14.735/2023).', content_status = 'current' where id = '5552a96c-d100-4ce6-90eb-5b6b66370d63' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Direitos Humanos', topic_text = 'DIREITOS HUMANOS (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Conceitos fundamentais e evolução histórica dos direitos humanos; 2. Declaração Universal dos Direitos Humanos e principais tratados internacionais assinados pelo Brasil; 3. Convenção Americana sobre Direitos Humanos (Pacto de San José da Costa Rica); 4. Normas constitucionais sobre direitos humanos; 5. Princípios aplicáveis à atividade policial: legalidade, proporcionalidade, dignidade humana, presunção de inocência; 6. Prevenção e combate à tortura; 7. Tratamento de pessoas custodiadas; 8. Uso proporcional e progressivo da força pela polícia; 9. Controle externo da atividade policial e atuação do Ministério Público. 10.Direitos e Proteção de Grupos Vulneráveis: 10.1. Doutrina, legislação e jurisprudência (nacional e convencional) sobre: pessoas em situação de rua, pessoas LGBTQIA+, pessoas com deficiência, racismo, violência obstétrica, violência doméstica e violência de gênero.', content_status = 'current' where id = 'f68fb13d-1bda-4db2-8dbb-c08678406235' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Criminologia', topic_text = 'CRIMINOLOGIA (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Conceito, objeto e métodos da Criminologia; 2. Teorias sociológicas, psicológicas e biológicas da criminalidade; 3. Classificação e tipologia dos delitos; 4. Estudo da conduta desviada e criminalidade organizada; 5. Reincidência e perigosidade; 6. Etiologia e prevenção do crime; 7. Relações entre criminalidade e desigualdade social; 8. Papel das instituições policiais no controle formal e informal da criminalidade; 9. Políticas públicas de prevenção ao crime.', content_status = 'current' where id = 'f4cfb6a9-d5fd-471b-9e3a-f23f0f2f97f3' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';
update public.syllabus_topics set discipline = 'Medicina Legal', topic_text = 'MEDICINA LEGAL (Edital nº 02/2025 PC-PI (FGV), Anexo I): 1. Noções fundamentais de medicina legal e suas aplicações na investigação criminal; 2. Tanatologia: morte aparente, real e suas fases, fenômenos cadavéricos e estimativa do tempo de morte; 3. Traumatologia forense: tipos de lesões, classificação médico-legal, armas e instrumentos lesivos, mecanismo de ação; 4. Sexologia forense: crimes sexuais, exames em vítimas e agressores; 5. Exames periciais: exame de corpo de delito direto e indireto, importância da preservação da cena do crime; 6. Identificação humana: métodos e relevância em perícias investigativas; 7. Responsabilidade médico-legal.', content_status = 'current' where id = '708266c8-259f-4e60-a5a5-5ee175bc2b14' and edition_id = '0649a19f-f691-4110-84ca-a3342ba77192';

-- Delegado de Polícia Civil
update public.syllabus_topics set discipline = 'Legislação e Conhecimentos Regionais', topic_text = 'LEGISLAÇÃO E CONHECIMENTOS REGIONAIS (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Legislação: 1.1. Lei Orgânica Nacional das Polícias Civis (Lei nº 14.735/2023): 1.1.1. Disposições gerais e princípios. 1.1.2. Organização das carreiras policiais. 1.1.3. Competências da Polícia Civil. 1.1.4. Direitos, deveres, garantias e vedações. 1.2. Estatuto da Polícia Civil do Estado do Piauí (Lei Complementar Estadual nº 37/2004 e Lei Complementar Estadual nº 318/2025). 1.2.1. Da Estrutura da Polícia Civil. 1.2.2. Da Carreira de Delegado de Polícia. 1.2.3. Dos deveres, proibições e transgressões disciplinares. 1.2.4. Da responsabilidade e das penalidades. 1.2.5. Do processo administrativo disciplinar. 1.2.6. Da progressão e da promoção na carreira. 1.2.7. Da aposentadoria e das disposições gerais. 1.2.8. Da vedação ao acúmulo de funções e exercício de outras atividades. 1.3. Estrutura Organizacional da Polícia Civil do Piauí (Decreto Estadual nº 22.223/2023 e suas alterações); 2. Conhecimentos Regionais: 2.1. Aspectos históricos relevantes do Estado do Piauí: formação territorial, processos coloniais e movimentos sociais locais; 2.2. Geografia física e humana: relevo, clima, hidrografia, vegetação, população, densidade demográfica e principais atividades econômicas; 2.3. Divisão político-administrativa: estrutura do estado, municípios e regiões de desenvolvimento; 2.4. Cultura piauiense: manifestações culturais, patrimônio material e imaterial, festas populares, artes, literatura, música e tradições; 2.5. Indicadores sociais e econômicos recentes: IDH, segurança pública, saúde, educação, mobilidade e desenvolvimento regional; 2.6. Estrutura do governo estadual, políticas públicas, programas sociais e desafios contemporâneos; 2.7. Temas de atualidade que impactam o Estado do Piauí: segurança, economia, meio ambiente, políticas de inclusão e sustentabilidade.', content_status = 'current' where id = '2cc876f9-885a-438a-82bd-7b35b2a55079' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direito Constitucional', topic_text = 'DIREITO CONSTITUCIONAL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Teoria da Constituição. 1.1. Conceito, Objeto e Classificações das Constituições. 1.2. Poder Constituinte: Titularidade, espécies (originário, derivado, decorrente, difuso), características e limites do poder constituinte originário. 1.3. Mutação Constitucional e Reforma Constitucional: Emendas e Revisão. 1.4. Supremacia da Constituição e o Bloco de Constitucionalidade. 1.5. Normas Constitucionais: Classificação quanto à eficácia e aplicabilidade (normas de eficácia plena, contida e limitada). 2. Controle de Constitucionalidade. 2.1. Conceito e Histórico. 2.2. Sistemas de Controle de Constitucionalidade: Difuso e Concentrado. 2.3. Ação Direta de Inconstitucionalidade (ADI). 2.4. Ação Declaratória de Constitucionalidade (ADC). 2.5. Arguição de Descumprimento de Preceito Fundamental (ADPF). 2.6. Ação Direta de Inconstitucionalidade por Omissão (ADO). 2.7. Recurso Extraordinário. 2.8. Efeitos das decisões em controle de constitucionalidade. 3. Direitos e Garantias Fundamentais. 3.1. Direitos e Deveres Individuais e Coletivos (art. 5º da CF). 3.2. Direitos Sociais (arts. 6º a 11 da CF). 3.3. Nacionalidade (arts. 12 e 13 da CF). 3.4. Direitos Políticos (arts. 14 a 16 da CF). 3.5. Partidos Políticos (art. 17 da CF). 4. Organização do Estado. 4.1. Organização Político-Administrativa da República Federativa do Brasil (arts. 18 e 19 da CF). 4.2. Repartição de Competências. 4.3. Intervenção Federal (arts. 34 a 36 da CF). 4.4. Administração Pública (arts. 37 a 41 da CF). 5. Organização dos Poderes. 5.1. Poder Legislativo (arts. 44 a 70 da CF). 5.2. Poder Executivo (arts. 76 a 91 da CF). 5.3. Poder Judiciário (arts. 92 a 126 da CF). 5.4. Funções Essenciais à Justiça (arts. 127 a 135 da CF). 6. Defesa do Estado e das Instituições Democráticas. 6.1. Estado de Defesa (arts. 136 e 137 da CF). 6.2. Estado de Sítio (arts. 138 e 139 da CF). 6.3. Forças Armadas (arts. 142 e 143 da CF). 7. Segurança Pública. 7.1. Disposições Gerais (art. 144 da CF). 7.2. Órgãos de Segurança Pública. 7.3. Atribuições da Polícia Civil. 8. Ordem Social. 8.1. Base e Objetivos da Ordem Social. 8.2. Seguridade Social (arts. 194 a 204 da CF). 8.3. Educação, Cultura e Desporto (arts. 205 a 217 da CF). 8.4. Meio Ambiente (art. 225 da CF). 8.5. Família, Criança, Adolescente, Jovem e Idoso (arts. 226 a 230 da CF). 9. Constituição do Estado do Piauí. 9.1. Princípios Fundamentais do Estado do Piauí. 9.2. Direitos e Garantias Fundamentais no âmbito estadual. 9.3. Organização dos Poderes Estaduais. 9.4. Administração Pública Estadual. 9.5. Segurança Pública Estadual.', content_status = 'current' where id = 'bd6227f4-9ece-4b9f-948f-e45446a51f90' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direito Administrativo', topic_text = 'DIREITO ADMINISTRATIVO (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Conceito e Fontes do Direito Administrativo. 1.1. Objeto do Direito Administrativo. 1.2. Fontes formais e materiais. 1.3. Regime Jurídico Administrativo. 2. Princípios da Administração Pública. 2.1. Princípios expressos (art. 37, caput, da CF). 2.2. Princípios implícitos. 2.3. Disposições da Lei de Introdução às Normas do Direito Brasileiro (LINDB) aplicáveis ao Direito Administrativo (Lei nº 13.655/2018). 3. Administração Pública. 3.1. Conceitos. 3.2. Estrutura da Administração Pública. 3.3. Desconcentração e Descentralização. 3.4. Órgãos Públicos. 3.5. Agentes Públicos. 4. Atos Administrativos. 4.1. Conceito, Requisitos. 4.2. Atributos. 4.3. Classificação. 4.4. Espécies de Atos Administrativos. 4.5. Perfeição, Validade, Eficácia, Revogação, Anulação e Convalidação. 5. Poderes da Administração Pública. 5.1. Poder Hierárquico. 5.2. Poder Disciplinar. 5.3. Poder Regulamentar. 5.4. Poder de Polícia. 5.5. Abuso de Poder. 5.6. Lei nº 13.869/2019. 6. Organização Administrativa da Polícia Civil do Estado do Piauí. 6.1. Estrutura e atribuições conforme a Lei Complementar Estadual nº 37/2004 e a Lei Complementar Estadual nº 318/2025. 6.2. Regime Jurídico dos Servidores da Polícia Civil do Piauí. 7. Licitações e Contratos Administrativos. 7.1. Lei nº 14.133/2021. 7.2. Contratos Administrativos. 8. Serviços Públicos. 8.1. Conceito, classificação, princípios. 8.2. Formas de Prestação. 9. Responsabilidade Civil do Estado. 9.1. Evolução histórica. 9.2. Teoria do Risco Administrativo. 9.3. Causas excludentes e atenuantes. 9.4. Dano, nexo causal e conduta. 9.5. Responsabilidade por atos legislativos e judiciais. 9.6. Responsabilidade individual de agentes públicos. 10. Bens Públicos. 10.1. Conceito e Classificação. 10.2. Afetação e desafetação. 10.3. Regime jurídico. 10.4. Formas de utilização. 11. Intervenção do Estado na Propriedade Privada. 11.1. Limitações Administrativas. 11.2. Ocupação Temporária. 11.3. Servidão Administrativa. 11.4. Requisição Administrativa. 11.5. Tombamento. 11.6. Desapropriação. 12. Controle da Administração Pública. 12.1. Controle Interno e Externo. 12.2. Controle Legislativo. 12.3. Controle Jurisdicional. 12.4. Controle Administrativo. 13. Improbidade Administrativa.', content_status = 'current' where id = '9fc4243b-fe0f-461b-b705-57873fb33563' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direito Penal', topic_text = 'DIREITO PENAL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Princípios Fundamentais do Direito Penal. 1.1. Princípios da Legalidade, Anterioridade, Irretroatividade, Culpabilidade, Humanidade, Insignificância/Bagatela, Intervenção Mínima, Fragmentariedade e Subsidiariedade. 2. Aplicação da Lei Penal. 2.1. Lei Penal no Tempo. 2.2. Lei Penal no Espaço. 2.3. Contagem de prazos. 2.4. Analogia. 2.5. Interpretação da Lei Penal. 3. Teoria Geral do Crime. 3.1. Conceito de crime. 3.2. Fato Típico. 3.3. Dolo e Culpa. 3.4. Erro de Tipo. 3.5. Ilicitude. 3.6. Culpabilidade. 3.7. Erro de Proibição. 3.8. Coação irresistível e obediência hierárquica. 4. Concurso de Pessoas. 4.1. Autoria e Participação. 4.2. Teorias. 4.3. Punibilidade do partícipe. 5. Teoria da Pena. 5.1. Conceito, finalidades e espécies de penas. 5.2. Penas privativas de liberdade. 5.3. Penas restritivas de direitos. 5.4. Pena de multa. 5.5. Suspensão Condicional da Pena. 5.6. Livramento Condicional. 5.7. Efeitos da condenação. 5.8. Reabilitação. 5.9. Medidas de Segurança. 6. Extinção da Punibilidade. 6.1. Causas de extinção. 6.2. Prescrição. 6.3. Decadência e Perempção. 7. Crimes Contra a Pessoa. 7.1. Homicídio. 7.2. Lesões Corporais. 7.3. Periclitação da Vida e da Saúde. 7.4. Rixa. 7.5. Crimes contra a Honra. 7.6. Crimes contra a Liberdade Individual. 8. Crimes Contra o Patrimônio. 8.1. Furto. 8.2. Roubo e Extorsão. 8.3. Dano. 8.4. Apropriação Indébita. 8.5. Estelionato e Outras Fraudes. 8.6. Receptação. 9. Crimes Contra a Propriedade Imaterial. 9.1. Crimes contra a Propriedade Industrial. 9.2. Crimes contra a Propriedade Intelectual. 10. Crimes Contra a Dignidade Sexual. 10.1. Estupro e demais crimes sexuais. 10.2. Satisfação de Lascívia Mediante Presença de Criança ou Adolescente. 10.3. Registro Não Autorizado de Intimidade Sexual. 11. Crimes Relacionados à Família e Relações de Dependência. 11.1. Bigamia. 11.2. Falsa Identidade. 11.3. Abandono Material. 12. Crimes Contra a Incolumidade Pública. 12.1. Crimes de Perigo Comum. 12.2. Crimes contra a Segurança dos Meios de Comunicação e Transporte. 12.3. Crimes contra a Saúde Pública. 13. Crimes Contra a Paz Pública. 13.1. Associação Criminosa. 13.2. Constituição de Milícia Privada. 14. Crimes Contra a Fé Pública. 14.1. Moeda Falsa. 14.2. Falsidade de Documento Público e Particular. 14.3. Falsidade Ideológica. 14.4. Falsificação de Carteira de Trabalho e Previdência Social. 15. Crimes Contra a Administração Pública. 15.1. Crimes Praticados por Funcionário Público Contra a Administração em Geral. 15.2. Crimes Praticados por Particular Contra a Administração em Geral. 15.3. Crimes Contra a Administração da Justiça. 15.4. Crimes Contra as Finanças Públicas. 16. Crimes em Licitações e Contratos Administrativos (Capítulo II-B do Código Penal). 17. Lei das Contravenções Penais (Decreto-Lei nº 3.688/1941). 18. Crimes de Trânsito (Lei nº 9.503/1997). 19. Crimes Eleitorais (Lei nº 4.737/1965). 20. Crimes contra a Ordem Tributária, Econômica e Relações de Consumo (Lei nº 8.137/1990). 21. Crimes de Abuso de Autoridade (Lei nº 13.869/2019). 22. Crimes de Tráfico de Drogas (Lei nº 11.343/2006). 23. Crimes Resultantes de Preconceito de Raça ou de Cor (Lei nº 7.716/1989). 24. Organizações Criminosas (Lei nº 12.850/2013). 25. Crimes contra o Meio Ambiente (Lei nº 9.605/1998). 26. Estatuto da Criança e do Adolescente - Crimes (Lei nº 8.069/1990). 27. Estatuto do Idoso - Crimes (Lei nº 10.741/2003). 28. Estatuto do Desarmamento (Lei nº 10.826/2003). 29. Crimes de Tortura (Lei nº 9.455/1997). 30. Violência Doméstica e Familiar Contra a Mulher (Lei nº 11.340/2006). 31. Violência Doméstica e Familiar Contra Criança e Adolescente - Lei Henry Borel (Lei nº 14.344/2022). 32. Crimes Hediondos (Lei nº 8.072/1990). 33. Crimes Contra o Sistema Financeiro Nacional (Lei nº 7.492/1986). 34. Lavagem ou Ocultação de Bens, Direitos e Valores (Lei nº 9.613/1998). 35. Crimes Cibernéticos.', content_status = 'current' where id = '2b376edb-fecd-49d2-b4bc-1b341b4d3cd9' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direito Processual Penal', topic_text = 'DIREITO PROCESSUAL PENAL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Princípios Fundamentais do Processo Penal. 1.1. Princípios Constitucionais do Processo Penal. 2. Sistemas Processuais Penais. 2.1. Sistema Acusatório, Inquisitivo e Misto. 3. Inquérito Policial. 3.1. Conceito, natureza jurídica, características, finalidade. 3.2. Notitia criminis. 3.3. Diligências policiais. 3.4. Indiciamento. 3.5. Prazo para conclusão. 3.6. Encerramento do inquérito. 3.7. Arquivamento. 3.8. Vícios do inquérito policial. 3.9. Valor probatório do inquérito. 3.10. Atribuições do Delegado de Polícia no inquérito policial. 4. Ação Penal. 4.1. Conceito e condições da ação. 4.2. Classificação. 4.3. Princípios da ação penal. 4.4. Queixa-crime. 5. Competência. 5.1. Conceito e critérios de fixação. 5.2. Conexão e Continência. 5.3. Prevenção. 5.4. Desaforamento. 6. Prova. 6.1. Conceito, objeto, meios e princípios. 6.2. Ônus da prova. 6.3. Meios de prova. 6.4. Provas ilícitas. 6.5. Cadeia de custódia. 7. Medidas Cautelares Pessoais. 7.1. Prisão em flagrante. 7.2. Prisão preventiva. 7.3. Prisão temporária. 7.4. Liberdade provisória com ou sem fiança. 7.5. Medidas cautelares diversas da prisão. 8. Prisão e Liberdade Provisória (Arts. 283 a 350 do CPP). 9. Citações e Intimações. 9.1. Conceito, formas e finalidades. 10. Sentença Penal. 10.1. Conceito, classificação, requisitos. 10.2. Nulidades da sentença. 11. Recursos. 11.1. Conceito, princípios, espécies. 11.2. Recurso em sentido estrito. 11.3. Apelação. 11.4. Habeas Corpus. 11.5. Recurso Especial e Recurso Extraordinário. 11.6. Revisão Criminal. 12. Nulidades. 12.1. Conceito, princípios, classificação. 12.2. Vícios insanáveis e sanáveis. 12.3. Momento para arguição. 13. Procedimentos Especiais do Código de Processo Penal. 13.1. Procedimento relativo aos crimes de responsabilidade dos funcionários públicos. 13.2. Processo e julgamento dos crimes de calúnia e injúria. 13.3. Procedimento do Tribunal do Júri. 14. Lei de Prisão Temporária (Lei nº 7.960/1989). 15. Lei do Depoimento Especial (Lei nº 13.431/2017). 16. Investigação Criminal Conduzida pelo Delegado de Polícia (Lei nº 12.830/2013). 17. Lei de Proteção a Vítimas e Testemunhas (Lei nº 9.807/1999). 18. Juizados Especiais Criminais (Lei nº 9.099/1995). 19. Colaboração Premiada (Lei nº 12.850/2013). 20. Lei de Interceptação Telefônica (Lei nº 9.296/1996). 21. Apuração de Atos Infracionais - ECA (Lei nº 8.069/1990); 22. Investigação Criminal Digital: 22.1. Busca e apreensão de dispositivos eletrônicos e evidências digitais, 22.2. Quebra de sigilo telemático e cadeia de custódia digital, 22.3. Conhecimentos técnicos aplicados à investigação criminal: redes de computadores, protocolos de internet, ataques cibernéticos, malware, criptografia, blockchain e criptomoedas', content_status = 'current' where id = '3fd7039b-bdde-458d-9ac3-20cdf7020b3a' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direito Civil', topic_text = 'DIREITO CIVIL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Lei de Introdução às Normas do Direito Brasileiro (LINDB). 1.1. Vigência e aplicação das normas jurídicas. 1.2. Vacatio legis. 1.3. Conflito de leis no tempo e no espaço. 1.4. Revogação de normas. 2. Parte Geral do Código Civil. 2.1. Das Pessoas Naturais. 2.2. Das Pessoas Jurídicas. 2.3. Domicílio. 2.4. Dos Bens. 2.5. Dos Fatos Jurídicos. 2.6. Atos jurídicos lícitos e ilícitos. 2.7. Prescrição e Decadência. 2.8. Prova dos negócios jurídicos. 3. Direito de Família. 3.1. Casamento. 3.2. Relações de parentesco. 3.3. Regime de bens. 3.4. Dissolução da sociedade e do vínculo conjugal. 3.5. União estável. 3.6. Tutela, curatela e tomada de decisão apoiada. 4. Direito das Obrigações. 4.1. Modalidades das obrigações. 4.2. Transmissão, adimplemento, extinção e inadimplemento das obrigações. 5. Responsabilidade Civil. 5.1. Obrigação de indenizar. 5.2. Responsabilidade civil objetiva e subjetiva. 5.3. Excludentes de responsabilidade. 5.4. Dano material e moral. 5.5. A repercussão da esfera criminal na responsabilidade civil. 5.6. Responsabilidade civil do incapaz. 6. Estatuto da Criança e do Adolescente - Aspectos Civis (Lei nº 8.069/1990). 7. Estatuto do Idoso - Aspectos Civis (Lei nº 10.741/2003). 8. Código de Defesa do Consumidor - Aspectos Civis (Lei nº 8.078/1990). 9. Lei de Parcelamento do Solo Urbano (Lei nº 6.766/1979). 10. Estatuto da Advocacia (Lei nº 8.906/1994). 10. Lei do Marco Civil da Internet - Lei nº 12.965, de 23 de abril de 2014.', content_status = 'current' where id = '2b106279-1fd5-4580-a04d-3da0829e1d3a' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Direitos Humanos', topic_text = 'DIREITOS HUMANOS (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Conceito, Evolução e Características dos Direitos Humanos. 1.1. Dimensões/Gerações de Direitos Humanos. 1.2. Características e fundamentação. 2. Direito Internacional dos Direitos Humanos e o Direito Brasileiro. 2.1. Relação entre o direito internacional dos direitos humanos e o direito interno. 2.2. O procedimento de incorporação dos tratados de direitos humanos na perspectiva da Constituição Federal. 2.3. Hierarquia dos tratados de direitos fundamentais na ordem jurídica interna brasileira. 2.4. Os princípios que regem as relações internacionais do Brasil. 3. Sistema Global de Proteção dos Direitos Humanos. 3.1. Organização das Nações Unidas (ONU). 3.2. Declaração Universal dos Direitos Humanos (1948). 3.3. Pacto Internacional de Direitos Civis e Políticos (1966). 3.4. Pacto Internacional de Direitos Econômicos, Sociais e Culturais (1966). 4. Sistema Regional Interamericano de Proteção dos Direitos Humanos. 4.1. Organização dos Estados Americanos (OEA). 4.2. Convenção Americana sobre Direitos Humanos (Pacto de San José da Costa Rica). 4.3. Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos. 5. Controle de Convencionalidade. 5.1. Conceito, fundamentos e modalidades. 5.2. O papel do Supremo Tribunal Federal e do Superior Tribunal de Justiça no controle de convencionalidade. 6. Direitos Humanos na Constituição Federal de 1988. 6.1. Dignidade da Pessoa Humana como fundamento da República. 6.2. Direitos consagrados nos tratados internacionais de direitos humanos dos quais o Brasil for parte. 7. Direitos e Proteção de Grupos Vulneráveis. 7.1. Doutrina, legislação e jurisprudência sobre grupos vulneráveis. 7.2. Direitos dos Povos Originários. 8. Direitos Humanos e Atividade Policial. 8.1. O papel das forças de segurança na promoção e proteção dos Direitos Humanos. 8.2. Prevenção e combate à tortura e maus-tratos. 8.3. Regras de uso da força e de armas de fogo pela ONU. 8.4. Regras Mínimas Padrão das Nações Unidas para o Tratamento de Prisioneiros (Regras de Mandela). 8.5. Heteroidentificação e os direitos dos candidatos autodeclarados negros em concursos públicos.', content_status = 'current' where id = '8f9cdb9f-e7a5-4b08-99f0-8ee65d8d2485' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
update public.syllabus_topics set discipline = 'Ciências Forenses', topic_text = 'CIÊNCIAS FORENSES (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Medicina Legal: 1.1. Conceito e Divisão da Medicina Legal. 1.1.1. Histórico e importância para o Direito. 1.1.2. Perícia médico-legal. 1.2. Antropologia Forense. 1.2.1. Identificação humana. 1.2.2. Papiloscopia, prosopografia, odontologia legal, identificação por DNA. 1.2.3. Reconhecimento facial automatizado. 1.2.4. Aplicação de inteligência artificial na identificação pericial. 1.3. Sexologia Forense. 1.3.1. Hímen, gravidez, parto, aborto, crimes sexuais. 1.4. Traumatologia Forense. 1.4.1. Lesões e suas classificações. 1.4.2. Lesões por instrumentos contundentes, cortantes, perfurantes, perfurocortantes, perfurocontundentes. 1.4.3. Asfixiologia forense. 1.4.4. Balística forense. 1.5. Tanatologia Forense. 1.5.1. Morte. 1.5.2. Fenômenos cadavéricos. 1.5.3. Data da morte. 1.5.4. Causas jurídicas da morte. 1.5.5. Necropsia. 1.6. Toxicologia Forense. 1.6.1. Conceito e importância. 1.6.2. Intoxicações por álcool, entorpecentes e outras substâncias. 1.6.3. Exames toxicológicos. 1.7. Psicopatologia Forense. 1.7.1. Sanidade mental e imputabilidade penal. 1.7.2. Doenças mentais e transtornos de personalidade com repercussão penal. 1.7.3. Simulação e dissimulação. 1.7.4. Perícia psiquiátrica forense. 1.8. Criminologia e Vitimologia Forense. 1.8.1. Aspectos médico-legais da criminalidade e da vitimização. 1.9. Documentoscopia e Grafoscopia. 1.9.1. Conceitos fundamentais. 1.9.2. Análise de documentos. 1.9.3. Análise de escrita e assinaturas. 1.9.4. Falsificações; 2. Criminologia: 2.1. Conceito e Objeto da Criminologia. 2.1.1. Objeto da Criminologia. 2.1.2. Método da Criminologia. 2.1.3. Criminologia Crítica e Criminologia Positivista. 2.2. Escolas Criminológicas. 2.2.1. Escola Clássica. 2.2.2. Escola Positiva. 2.2.3. Sociologia Criminal. 2.2.4. Teorias do Etiquetamento. 2.2.5. Criminologia Crítica e Abolicionismo Penal. 2.2.6. Teorias do Conflito. 2.2.7. Crimes em massa e criminologia contemporânea. 2.3. Vitimologia. 2.3.1. Conceito e Classificação das Vítimas. 2.3.2. Papel da vítima na gênese do delito. 2.3.3. Vitimização primária, secundária e terciária. 2.3.4. Políticas de assistência à vítima. 2.4. Controle Social do Crime. 2.4.1. Conceito de controle social. 2.4.2. Controle social formal e informal. 2.4.3. Agências de controle social. 2.4.4. Prevenção do delito. 2.5. Criminologia e Política Criminal. 2.5.1. Relação entre Criminologia, Direito Penal e Política Criminal. 2.5.2. Modelos de Política Criminal. 2.6. Criminologia e Atuação Policial. 2.6.1. A importância do conhecimento criminológico para a investigação criminal e a gestão da segurança pública. 2.6.2. Perfil criminal. 2.6.3. Leitura e interpretação de indicadores de criminalidade e estatísticas criminais aplicadas à atuação policial; 2.6.4. Criminologia Digital: 2.6.4.1. Perfil do criminoso cibernético e análise de crimes digitais, 2.6.4.2. Deep web, dark web e ambientes digitais criminógenos, 2.6.4.3. Vitimização digital e prevenção de crimes cibernéticos.', content_status = 'current' where id = 'aeb08f94-f5b1-47d8-bed0-e6b09d655d03' and edition_id = 'c0ea9fc5-d65d-4f8c-a936-729f8824a072';
